// Worker entry for the Cloudflare spike.
//
// Wraps the worker that `opennextjs-cloudflare build` generates in
// .open-next/worker.js and adds the one thing it lacks: a `scheduled` handler.
// It replaces the Vercel cron in vercel.json (`/api/cron/warm-sitemaps`, every
// six hours) with a Cron Trigger declared in wrangler.jsonc. The trigger calls
// the route through the worker's own fetch handler, with the same bearer token
// Vercel sends, so the route itself does not change.

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as openNextHandler } from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string; CRON_WARM_ORIGIN?: string };

const WARM_SITEMAPS_PATH = "/api/cron/warm-sitemaps";

export default {
  fetch: openNextHandler.fetch,

  async scheduled(
    _controller: { cron: string; scheduledTime: number },
    env: Env,
    ctx: { waitUntil(promise: Promise<unknown>): void }
  ): Promise<void> {
    const headers = new Headers();
    if (env.CRON_SECRET) headers.set("authorization", `Bearer ${env.CRON_SECRET}`);
    // The origin only routes the request inside this worker; it is never
    // fetched over the network.
    const origin = env.CRON_WARM_ORIGIN || "http://localhost";
    const request = new Request(new URL(WARM_SITEMAPS_PATH, origin), { headers });
    ctx.waitUntil(openNextHandler.fetch(request, env, ctx));
  },
};

// Durable Object classes the cache overrides in open-next.config.ts bind to.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache } from "../.open-next/worker.js";
